<?php
namespace App\Http\Controllers; use App\Models\RoomType; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class RoomTypeController extends Controller { public function index(Request $r){$pid=$r->user()->property_id;$types=RoomType::withCount('rooms')->where('property_id',$pid)->paginate(20);return view('room-types.index',compact('types'));} public function store(Request $r){$pid=$r->user()->property_id;$d=$r->validate(['name'=>'required|max:120','code'=>['required','max:30',Rule::unique('room_types')->where(fn($q)=>$q->where('property_id',$pid))],'description'=>'nullable','base_occupancy'=>'required|integer|min:1|max:20','max_adults'=>'required|integer|min:1|max:20','max_children'=>'required|integer|min:0|max:20','base_rate'=>'required|numeric|min:0']);RoomType::create($d+['property_id'=>$pid,'is_active'=>true]);return back()->with('success','Room type created.');} }
